CREATE TABLE IF NOT EXISTS admin_users(id CHAR(36) PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at VARCHAR(24) NOT NULL, updated_at VARCHAR(24) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_sessions(token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, credential_version CHAR(64) NOT NULL, created_at VARCHAR(24) NOT NULL, expires_at VARCHAR(24) NOT NULL, revoked_at VARCHAR(24), INDEX user_session_expiry(expires_at), CONSTRAINT fk_user_sessions_user FOREIGN KEY(user_id) REFERENCES admin_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
